package com.automationstudio.engine.karate.worker;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import java.security.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
class SourceProjectionTest {@TempDir Path temp;private static byte[] bytes(){return "Feature: inert".getBytes(java.nio.charset.StandardCharsets.UTF_8);}private static String digest(byte[] b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}
 @Test void validatesWritesAndDeletes()throws Exception{Path root=temp.resolve("source");byte[] b=bytes();try(var p=new SourceProjection(root,100)){p.accept("features/a.feature",b.length,digest(b),b,100);assertArrayEquals(b,Files.readAllBytes(root.resolve("features/a.feature")));}assertFalse(Files.exists(root));}
 @Test void rejectsDigestSizeDuplicateTraversalAbsoluteAndLimits()throws Exception{byte[] b=bytes();try(var p=new SourceProjection(temp.resolve("a"),100)){assertThrows(Exception.class,()->p.accept("../x",b.length,digest(b),b,100));assertThrows(Exception.class,()->p.accept("/x",b.length,digest(b),b,100));assertThrows(Exception.class,()->p.accept("x",b.length+1,digest(b),b,100));assertThrows(Exception.class,()->p.accept("x",b.length,"00",b,100));p.accept("ok",b.length,digest(b),b,100);assertThrows(Exception.class,()->p.accept("ok",b.length,digest(b),b,100));}try(var p=new SourceProjection(temp.resolve("b"),1)){assertThrows(Exception.class,()->p.accept("x",b.length,digest(b),b,100));}try(var p=new SourceProjection(temp.resolve("c"),100)){assertThrows(Exception.class,()->p.accept("x",b.length,digest(b),b,1));}}
}
